package com.nexus.domain; import jakarta.persistence.*; import java.time.*;
@Entity @Table(name="notifications",indexes=@Index(columnList="recipient_id")) public class Notice{@Id @GeneratedValue(strategy=GenerationType.IDENTITY) public Long id; @Column(name="recipient_id") public Long recipientId; public Long incidentId; public Instant at; public String channel,delivery; @Column(length=4000) public String message; public boolean opened; public String providerId; protected Notice(){} public Notice(Long u,Long i,Instant at,String c,String d,String m){recipientId=u;incidentId=i;this.at=at;channel=c;delivery=d;message=m;}}
